xwikidoc.content:
{{groovy}}
  import com.xpn.xwiki.api.PropertyClass;
  import org.apache.commons.lang3.StringUtils;

  def displayMetadataPro(boolean quiet, boolean box)
  {
    // Converted from templates/macros.vm
    def unwrapXPropertyDisplay = { d ->
      return StringUtils.removeEnd(StringUtils.removeStart(d, '{{html clean="false" wiki="false"}}'), '{{/html}}')
    };

    def res = services.query.hql(
      "select distinct doc.fullName, doc.title " +
      "from " +
      "  XWikiDocument doc, " +
      "  BaseObject metadataSetObj, " +
      "  DBStringListProperty includedSpacesProperty " +
      "join " +
      "  includedSpacesProperty.list includedSpace " +
      "where " +
      "      doc.fullName <> 'MetadataPro.Code.MetadataSetTemplate' " +
      "  and doc.fullName = metadataSetObj.name " +
      "  and metadataSetObj.className = 'MetadataPro.Code.MetadataSetClass' " +
      "  and includedSpacesProperty.id.id = metadataSetObj.id " +
      "  and includedSpacesProperty.id.name = 'includedSpaces' " +
      "  and :currentLocation like concat(includedSpace, '.%')"
    ).bindValue('currentLocation', doc.fullName).execute();

    // Handle empty includedSpaces properties (which mean everywhere)
    // I didn't know how to do this in one query, but it would be better
    res.addAll(services.query.hql(
      "select distinct doc.fullName, doc.title " +
      "from " +
      "  XWikiDocument doc, " +
      "  BaseObject metadataSetObj, " +
      "  DBStringListProperty includedSpacesProperty " +
      "where " +
      "      doc.fullName <> 'MetadataPro.Code.MetadataSetTemplate' " +
      "  and doc.fullName = metadataSetObj.name " +
      "  and metadataSetObj.className = 'MetadataPro.Code.MetadataSetClass' " +
      "  and includedSpacesProperty.id.id = metadataSetObj.id " +
      "  and includedSpacesProperty.id.name = 'includedSpaces' " +
      "  and includedSpacesProperty.list is empty"
    ).execute());

    def boxStarted = false;
    if (res.isEmpty()) {
      if (!quiet) {
        println services.localization.render("metadatapro.nosetsforthislocation");
      }
    } else {
      def objectsToRender = [];
      def found = false;
      for (String[] r : res) {
        def (metadataSetFullName, metadataSetTitle) = r;
        if (metadataSetTitle.trim() == "") {
          metadataSetTitle = metadataSetFullName;
        }
        if (doc.getObject(metadataSetFullName) == null) {
          if (!found) {
            found = true;
            if (hasEdit && !quiet) {
              println services.localization.render("metadatapro.youcanaddaset");
              println ""
              println "{{html clean=false}}";
              println "<form method='post' action='" + doc.getURL("edit", "sheet=MetadataPro.Code.MetadataSetInstanceSheet") + "'>"
              println "<p style='display:flex;gap: 1ex; align-items: center'>"
              println "<label style='margin:0'>" + services.localization.render("metadatapro.metadatasetlabel") + " <select name='metadataset'>"
            }
          }
          if (hasEdit && !quiet) {
            println (
              "<option value='" +
              services.xml.escape(metadataSetFullName) +
              "'>" +
              services.xml.escape(metadataSetTitle) +
              "</option>"
            );
          }
        } else {
          objectsToRender.add(r);
        }
      }
      if (!quiet) {
        if (found) {
          println (
            "</select></label> " + 
            "<button name='editmetadataset' value='1' class='btn btn-primary'>" +
              services.localization.render("metadatapro.actions.add") +
            "</button></p></form>"
          );
          println "{{/html}}";
        } else {
          println services.localization.render("metadatapro.nomoresetsforthislocation");
        }
      }

      if (!objectsToRender.isEmpty()) {
        // println '{{html clean=false}}<form method="post" action="' + doc.getURL('preview') + '">{{/html}}'
        if (box) {
          println "{{html clean=false}}<section class='metadatapro-display'><h2>" + services.localization.render('metadatapro.box.title') + "</h2>{{/html}}";
          boxStarted = true;
        }
        if (!quiet) {
          println "\n----\n"
        }
        for (String[] r : objectsToRender) {
          def (metadataSetFullName, metadataSetTitle) = r;
          if (metadataSetTitle.trim() == "") {
            metadataSetTitle = metadataSetFullName;
          }
          def escapedSetFullName = services.xml.escape(metadataSetFullName);
          def heading = "=== " + services.rendering.escape(metadataSetTitle, doc.getSyntax());
          if (hasEdit) {
            def xredirect =  java.net.URLEncoder.encode(
              request.requestURI
                + (request.queryString ? ("?" + request.queryString) : ""),
              "UTF-8");
            println (
               "\n{{html clean=false}}"
               + "<div class='metadatapro-set'>"
               + "<form id='metadatapro-form-"
               + escapedSetFullName
               + "' method='post' action='"
               + doc.getURL("edit", "sheet=MetadataPro.Code.MetadataSetInstanceSheet&xredirect=" + xredirect)
               + "'><input type='hidden' name='metadataset' value='"
               + escapedSetFullName
               + "' /></form>"
               + "{{/html}}\n\n"
               + heading
               + " {{html}}"
               + "<span class='metadatapro-set-actions'>"
               + "<button name='editmetadataset' value='1' form='metadatapro-form-" + escapedSetFullName + "' class='btn-metadatapro-linklike btn btn-metadatapro-edit' aria-label='" + services.localization.render('metadatapro.actions.edit') + "'>"
               + '<span class="fa fa-pencil" aria-hidden="true"></span>'
               + "</button> "
               + "<button name='deletemetadataset' value='1' form='metadatapro-form-" + escapedSetFullName + "' class='btn-metadatapro-linklike btn-metadatapro-delete' aria-label='" + services.localization.render('metadatapro.actions.delete') + "'>"
               + '<span class="fa fa-times" aria-hidden="true"></span>'
               + "</button>"
               + "</span>"
               + "{{/html}}\n\n"
            );
          } else {
            println heading;
          }
          def obj = doc.getObject(metadataSetFullName);
          if (obj) {
              for (PropertyClass property : obj.xWikiClass.properties) {
                def v = unwrapXPropertyDisplay(doc.display(property.getName())).trim();
                if (v) {
                  // display is supposed to issue an html macro but doesn't, and will when it gets fixed,
                  // so we prepare for both situations by wrapping with html manually and removing the potential html macro returned by display using unwrapXPropertyDisplay
                  println "|= " + property.prettyName + " | (((\n\n{{html}}\n" + v + "\n{{/html}}\n\n)))";
                }
              }
              println "\n{{html clean=false}}\n</div>\n{{/html}}"
          }
        }
        if (boxStarted) {
          println "\n{{html clean=false}}\n</section>\n{{/html}}";
        }
        /*println (
          '\n\n{{html clean=false}}'
          + '<div class="btn-group">'
          + '<input class="btn btn-primary" type="submit" name="action_save" value="' + services.localization.render('saveandview') + '">'
          + '</div>'
          + '<input type="hidden" name="xaction" value="save"/>'
          + '</form>'
          + '{{/html}}'
        );*/
      }
    }
  }
{{/groovy}}

property.code:
.metadatapro-display {
  border:1px solid;
  border-radius:var(--border-radius-base);
  background:var(--panel-bg);
  color:var(--panel-default-text);
  h2 {
    border-top-left-radius:var(--border-radius-base);
    border-top-right-radius:var(--border-radius-base);
    margin-top:0;
    padding-top:0;
    text-align:right;
    font-size:1em;
    background:var(--panel-header-bg);
    color:var(--panel-header-text);
    font-weight:bold;
    padding:1ex
  }
  > .metadatapro-set {
    margin-bottom:0
  }
}
.metadatapro-set {
  padding:0 .5ex;
  margin-bottom:2em;
  > h3 {
    padding-left:3px;
    margin:0
  }
  > table {
    margin:1ex 1ex 1ex 2ex;
    width:calc(100% - 3ex);
    > tbody > tr {
      &:nth-child(even) {
        background:rgba(0,0,0,0.05)
      }
      > td, > th {
        input {
          width: 100%;
        }
        border:0;
        padding:.5ex;
        p:first-child {
          padding-top:0;
          margin-top:0
        }
        p:last-child {
          padding-bottom:0;
          margin-bottom:0
        }
      }
    }
  }
}
.metadatapro-set-actions {
  display:inline-flex;
  float:right;
  gap:.5ex
}
.btn-metadatapro-linklike {
  background:transparent;
  padding:0 .25ex;
  color:var(--link-color);
  border:0;
}

.btn-metadatapro-linklike-danger {
  color: var(--brand-danger);
}

.btn-metadatapro-delete {
  color:var(--brand-danger)
}
